[h1]SETUP:[/h1]

[code]
{text-name}.new;
{text-name}.visible=1;
{text-name}.x=260;
{text-name}.y=600;
{text-name}.opacity=100;
{text-name}.width=320;
{text-name}.height=32;
{text-name}.text=some text;
{text-name}.fontcolor.r=255;
{text-name}.fontcolor.g=255;
{text-name}.fontcolor.b=255;
{text-name}.fontsize=22;
[/code]

[h1]CUSTOM PARAMS[/h1]
[code]
{text-name}.paramname=value;
[/code]

[h1]DELETE[/h1]
[code]
{text-name}.delete;
[/code]

[h1]SAVE / LOAD[/h1]
[code]
{text-name}.save;
[/code]

[code]
{text-name}.load;
[/code]

[code]
{text-name}.export;
[/code]


[h1]LOCAL = RENDERED IN CURRENT ROOM.[/h1]
[code]
{text-name}.local;
[/code]

[h1]GLOBAL = RENDERED AS MAIN UI.[/h1]
[code]
{text-name}.global;
[/code]

